// Calendly on a personal access token: every operation in its published API. actions.json is generated by
// `bun scripts/openapi-actions.ts calendly`; everything Calendly can report starts automations by webhook (triggers.ts).
import type { OwnApp } from "../index";
import { type Api, call, specActions } from "../openapi";
import { events, receive, triggers, unwatch, wanted, watch } from "./triggers";

const api: Api = {
  name: "Calendly",
  base: "https://api.calendly.com",
  tokenHelp: "calendly.com/integrations/api_webhooks",
};

export const calendly: OwnApp = {
  app: "calendly",
  name: "Calendly",
  logo: "/logos/calendly.svg",
  keyField: {
    label: "Personal access token",
    help: "In Calendly: Integrations → API and webhooks (calendly.com/integrations/api_webhooks) → Generate new token, then copy it. Automations use Calendly's webhooks, which need a paid Calendly plan (Standard or above); for the whole organization's meetings the token must belong to an owner or admin.",
    placeholder: "eyJ...",
  },
  async check(key) {
    const me = (await call(api, key, { method: "GET", path: "/users/me", query: [], headers: [] }, {})) as { resource: { name?: string; email?: string } };
    return me.resource.name || me.resource.email;
  },
  push: {
    events,
    triggers,
    start: (key, connection, event) => watch(api, key, connection, event),
    stop: (key, id) => unwatch(api, key, id),
    receive,
    wanted,
  },
  actions: await specActions(new URL("./actions.json", import.meta.url), api),
};
